public display NoYesId displayLoadPickComplete()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;

    select firstonly RecId from wmsPickingRoute
            where wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete
        exists join shipmentLoadLines
            where   shipmentLoadLines.PickingListNum == wmsPickingRoute.pickingRouteID 
        exists join shipmentLoadHeader 
            where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId &&
                shipmentLoadHeader.LoadId == this.LoadId;  

    if (wmsPickingRoute.RecId != 0)
    {
        return NoYes::No;
    }
    else
    {
        return NoYes::Yes;
    }
}

public display NoYesId displayPickComplete()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;

    select firstonly RecId from wmsPickingRoute
        exists join shipmentLoadLines
            where   shipmentLoadLines.PickingListNum == wmsPickingRoute.pickingRouteID  &&
                    shipmentLoadLines.ShipmentId == this.ShipmentId &&
                    wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete;

    if (wmsPickingRoute.RecId != 0)
    {
        return NoYes::No;
    }
    else
    {
        return NoYes::Yes;
    }
}

public display METOrderSplitGroup displayShipmentOrderSplitGroup()
{
    METSalesOrderShipmentLoadLines     shipmentLoadLines;

    select firstonly OrderSplitGroup from shipmentLoadLines
        where shipmentLoadLines.ShipmentId == this.ShipmentId;

    return shipmentLoadLines.OrderSplitGroup;
}

/// <summary>
/// Display customer name
/// </summary>
/// <returns>Name</returns>
public display DirPartyName displayCustName()
{
    return DirPartyTable::getName(CustTable::find(this.CustAccount).Party);
}

public display TMSCarrierCode displayShippingCarrier()
{
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    TMSSalesTable                       tmsSalesTable;

    select firstonly CarrierCode from tmsSalesTable
        exists join shipmentLoadLines
            order by OrderNum asc
                where tmsSalesTable.SalesId == shipmentLoadLines.OrderNum   &&
                    shipmentLoadLines.ShipmentId == this.ShipmentId;

    return tmsSalesTable.CarrierCode;
}

/// <summary>
///
/// </summary>
public static METSalesOrderShipmentLoadHeader findOrCreateOpenShipment(CustAccount                    _custAccount,
                                                                      METRoute                        _metRoute,
                                                                      METRouteStopNum                 _metRouteStop,
                                                                      SalesShippingDateConfirmed      _confirmedDate,
                                                                      InventLocationId                _inventLocationId,
                                                                      MetOrderTransactionType         _transactionType,
                                                                      boolean                         _findAndCreate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.CustAccount == _custAccount       &&
            metSalesOrderShipmentLoadHeader.Route == _metRoute                  &&
            metSalesOrderShipmentLoadHeader.RouteStopNum == _metRouteStop       &&
            metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate &&
            metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId      &&
            metSalesOrderShipmentLoadHeader.TransactionType == _transactionType &&
            metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.RecId != 0 || _findAndCreate == false)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.ShipmentId      = NumberSeq::newGetNum(InventParameters::numRefMetShippingID()).num();
    metSalesOrderShipmentLoadHeader.CustAccount     = _custAccount;
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = _confirmedDate;
    metSalesOrderShipmentLoadHeader.Route           = _metRoute;
    metSalesOrderShipmentLoadHeader.RouteStopNum    = _metRouteStop;
    metSalesOrderShipmentLoadHeader.Warehouse       = _inventLocationId;
    metSalesOrderShipmentLoadHeader.SiteId          = InventLocation::find(_inventLocationId).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = _transactionType;
    metSalesOrderShipmentLoadHeader.ShipmentStatus  = MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.validateWrite())
    {
        metSalesOrderShipmentLoadHeader.insert();
    }
    else //In case of validation fail, try again to search for open shipment. This may occur when multi thread is running and at same time two picking list executed and system tryed to insert shipment for same parameter.
    {
        select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.CustAccount == _custAccount       &&
                metSalesOrderShipmentLoadHeader.Route == _metRoute                  &&
                metSalesOrderShipmentLoadHeader.RouteStopNum == _metRouteStop       &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate &&
                metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId      &&
                metSalesOrderShipmentLoadHeader.TransactionType == _transactionType &&
                metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

            if (metSalesOrderShipmentLoadHeader.RecId != 0)
            {
                return metSalesOrderShipmentLoadHeader;
            }
    }

    return metSalesOrderShipmentLoadHeader;
}

public static METSalesOrderShipmentLoadHeader findOpenLoad(METRoute                     _metRoute,
                                                        SalesShippingDateConfirmed      _confirmedDate,
                                                        InventLocationId                _inventLocationId,
                                                        MetOrderTransactionType         _transactionType)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.Route == _metRoute                    &&
            metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate     &&
            metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId          &&
            metSalesOrderShipmentLoadHeader.LoadStatus == METLoadStatus::Open;

    return metSalesOrderShipmentLoadHeader;

}

public static void generateShipmentLoadFromExtraction(container         _soListFromExtraction,
                                                    boolean             _createShipment,
                                                    boolean             _skipShipmentLinesCreation)
{
    SalesTable                                  salesTable;
    METSalesOrderShipmentLoadCreationTmp        tmpTable;

    for (int i = 1; i <= conLen(_soListFromExtraction); i++)
    {
        salesTable = SalesTable::find(conPeek(_soListFromExtraction, i));

        if (salesTable.RecId)
        {
            tmpTable.clear();

            tmpTable.RouteStopNum = salesTable.METRouteStopNum;
            tmpTable.CustAccount = salesTable.CustAccount;
            tmpTable.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
            tmpTable.SiteId = salesTable.InventSiteId;
            tmpTable.Warehouse = salesTable.InventLocationId;
            tmpTable.Route = salesTable.METRoute;

            tmpTable.insert();
        }
    }

    METSalesOrderShipmentLoadHeader::createShippmentLoadFromTmpTable(tmpTable, _createShipment, _skipShipmentLinesCreation);
}

public static void createShippmentLoadFromTmpTable(METSalesOrderShipmentLoadCreationTmp     _tmpTable,
                                                  boolean                                   _createShipment,
                                                  boolean                                   _skipShipmentLinesCreation)
{
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;

    //Shipment creation and update
    while select _tmpTable
        group by CustAccount, ConfirmedShipDate, Warehouse, RouteStopNum, Route
    {

        salesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOrCreateOpenShipment(_tmpTable.CustAccount,
                                                                                                _tmpTable.Route,
                                                                                                _tmpTable.RouteStopNum,
                                                                                                _tmpTable.ConfirmedShipDate,
                                                                                                _tmpTable.Warehouse,
                                                                                                METOrderTransactionType::SalesOrder,
                                                                                                _createShipment);
        if (salesOrderShipmentLoadHeader.RecId)
        {
            if (_skipShipmentLinesCreation == false)
            {
                //METSalesOrderShipmentLoadLines::createShipmentLines(salesOrderShipmentLoadHeader);
            }

            if (_createShipment)
            {
                info(strFmt("Shipment %1 is created.", salesOrderShipmentLoadHeader.ShipmentId));
            }
            else
            {
                info(strFmt("Shipment %1 is updated.", salesOrderShipmentLoadHeader.ShipmentId));
            }
        }
    }

    MetLoadId       loadId;
    //Load creation and update
    while select _tmpTable
        group by ConfirmedShipDate, Warehouse, Route
    {
        loadId = METSalesOrderShipmentLoadHeader::consolidateShipmentAndCreateLoads(_tmpTable.Route,
                                                                                _tmpTable.ConfirmedShipDate,
                                                                                _tmpTable.Warehouse,
                                                                                METOrderTransactionType::SalesOrder,
                                                                                _createShipment);

        if (loadId)
        {
            if (_createShipment)
            {
                info(strFmt("Load %1 is created.", salesOrderShipmentLoadHeader.LoadId));
            }
            else
            {
                info(strFmt("Load %1 is updated.", salesOrderShipmentLoadHeader.LoadId));
            }
        }
    }

}

public static MetLoadId consolidateShipmentAndCreateLoads(METRoute                     _metRoute,
                                                        SalesShippingDateConfirmed      _confirmedDate,
                                                        InventLocationId                _inventLocationId,
                                                        MetOrderTransactionType         _transactionType,
                                                        boolean                         _createNewIfNotFound = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadHeader     loadHeader = METSalesOrderShipmentLoadHeader::findOpenLoad(_metRoute, _confirmedDate, _inventLocationId, METOrderTransactionType::SalesOrder);
    MetLoadId                           loadId = loadHeader.LoadId;

    if (loadId == '')
    {
        if (_createNewIfNotFound == true)
        {
            loadId = NumberSeq::newGetNum(InventParameters::numRefMetLoadID()).num();
        }
        else
        {
            return '';
        }
    }

    update_recordset metSalesOrderShipmentLoadHeader
        setting LoadId = loadId,
                LoadStatus = MetLoadStatus::Open
            where metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open     &&
                metSalesOrderShipmentLoadHeader.LoadStatus == MetLoadStatus::Open               &&
                metSalesOrderShipmentLoadHeader.Route == _metRoute                              &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate             &&
                metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId                  &&
                metSalesOrderShipmentLoadHeader.TransactionType == _transactionType;

    return loadId;

}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;
    boolean ret;

    ret = super();

    select firstonly RecId from shipmentLoadHeader
        where shipmentLoadHeader.ConfirmedShipDate == this.ConfirmedShipDate    &&
            shipmentLoadHeader.CustAccount == this.CustAccount                  &&
            shipmentLoadHeader.Warehouse == this.Warehouse                      &&
            shipmentLoadHeader.Route == this.Route                              &&
            shipmentLoadHeader.RouteStopNum == this.RouteStopNum                &&
            shipmentLoadHeader.ShipmentId != this.ShipmentId                    &&
            shipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

    if (shipmentLoadHeader.RecId != 0)
    {
        ret = checkFailed(strFmt("Open shipment '%1' exist for the same Customer, Warehouse, Ship date, route, route stop num. Hence, cannot create new.", shipmentLoadHeader.ShipmentId));
    }

    return ret;
}

public static void createShippmentLoadFromSalesTable(SalesId     _salesId,
                                                  boolean       _createShipment,
                                                  boolean       _skipShipmentLinesCreation)
{
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;
    SalesTable      salesTable = SalesTable::find(_salesId);

    if (salesTable.RecId == 0)
    {
        warning(strFmt("Sales order %1 is not valid, hence shipment create/update failed.", _salesId));
        return;
    }
    salesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOrCreateOpenShipment(salesTable.CustAccount,
                                                                                            salesTable.METRoute,
                                                                                            salesTable.METRouteStopNum,
                                                                                            salesTable.ShippingDateConfirmed,
                                                                                            salesTable.InventLocationId,
                                                                                            METOrderTransactionType::SalesOrder,
                                                                                            _createShipment);
    if (salesOrderShipmentLoadHeader.RecId)
    {
        if (_skipShipmentLinesCreation == false)
        {
            METSalesOrderShipmentLoadLines::createShipmentLines(salesOrderShipmentLoadHeader, salesTable);
        }

        MetLoadId       loadId;
        //Load creation and update
        loadId = METSalesOrderShipmentLoadHeader::consolidateShipmentAndCreateLoads(salesTable.METRoute,
                                                                                    salesTable.ShippingDateConfirmed,
                                                                                    salesTable.InventLocationId,
                                                                                    METOrderTransactionType::SalesOrder,
                                                                                    _createShipment);

        info(strFmt("Shipment '%1 is created / updated.", salesOrderShipmentLoadHeader.ShipmentId));
        info(strFmt("Load '%1' is created / updated.", loadId));
    }

}

/// <summary>
///
/// </summary>
public static METSalesOrderShipmentLoadHeader findByRecId(RefRecId     _recId, 
                                                boolean         _forUpdate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    if (_forUpdate)
    {
        metSalesOrderShipmentLoadHeader.selectForUpdate(true);
    }

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == _recId;

    return metSalesOrderShipmentLoadHeader;
}

/// <summary>
///
/// </summary>
public static void updateLoadStatus_old(MetLoadId       _loadId)
{
    METSalesOrderShipmentLoadHeader         metSalesOrderShipmentLoadHeader;
    MetLoadStatus                           metLoadStatusUpdate;
    boolean                                 loadedFound;
    boolean                                 shippedFound;

    select firstonly RecId from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.LoadId == _loadId &&
            metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.RecId != 0)
    {
        metLoadStatusUpdate = MetLoadStatus::Open;
    }
    else
    {
        while select ShipmentStatus, RecId from metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.LoadId == _loadId
        {
            if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Loaded)
            {
                loadedFound = true;
            }
            else if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Shipped)
            {
                shippedFound = true;
            }

            if (loadedFound == true && shippedFound == true)
            {
                break;
            }
        }

        if ((loadedFound == true && shippedFound == true) || (loadedFound == true && shippedFound == false))
        {
            metLoadStatusUpdate = MetLoadStatus::Loaded;
        }
        else if (loadedFound == false && shippedFound == true)
        {
            metLoadStatusUpdate = MetLoadStatus::Shipped;
        }
    }

    metSalesOrderShipmentLoadHeader.skipDataMethods(true);

    update_recordset metSalesOrderShipmentLoadHeader
        setting LoadStatus = metLoadStatusUpdate
            where metSalesOrderShipmentLoadHeader.LoadId == _loadId;

    info(strFmt("Load '%1' is updated with '%2' status.", _loadId, metLoadStatusUpdate));
}

public static void updateLoadStatus(MetLoadId       _loadId)
{
    METSalesOrderShipmentLoadHeader         metSalesOrderShipmentLoadHeader;
    MetLoadStatus                           metLoadStatusUpdate;

    select minof(ShipmentStatus) from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.LoadId == _loadId;

    switch (metSalesOrderShipmentLoadHeader.ShipmentStatus)
    {
        case MetShipmentStatus::Open :
            metLoadStatusUpdate = MetLoadStatus::Open;

            break;

        case MetShipmentStatus::Loaded :
            metLoadStatusUpdate = MetLoadStatus::Loaded;

            break;

        case MetShipmentStatus::Shipped :
            metLoadStatusUpdate = MetLoadStatus::Shipped;

            break;

        default :
            break;

    }


    metSalesOrderShipmentLoadHeader.skipDataMethods(true);

    update_recordset metSalesOrderShipmentLoadHeader
        setting LoadStatus = metLoadStatusUpdate
            where metSalesOrderShipmentLoadHeader.LoadId == _loadId;

    info(strFmt("Load '%1' is updated with '%2' status.", _loadId, metLoadStatusUpdate));
}
